package db

// genSource is one supplemental 3.3.5 acquisition source, generated by
// tools/gen_sources.py for items whose only upstream sources are
// WotLK-Classic-only and are stripped at parse time (see sources_gen.go).
// Kind is "drop" (NPCID+ZoneID), "vendor" (NPCID+Name+ZoneID) or "object"
// (Name+ZoneID, e.g. a chest).
type genSource struct {
	Kind   string
	NPCID  int
	Name   string
	ZoneID int
}

// addSupplementalSources attaches generated true sources to items the
// upstream data cannot source. Only items with no sources at all are
// touched — the tables fill holes, they never override upstream data.
// Shared by the WotLK and Cata loaders (their generators emit the
// same genSource shape).
func (d *Database) addSupplementalSources(m map[int]genSource) {
	for id, gs := range m {
		it := d.Items[id]
		if it == nil || len(it.Sources) > 0 {
			continue
		}
		switch gs.Kind {
		case "drop":
			it.Sources = append(it.Sources, Source{Drop: &DropSource{NPCID: gs.NPCID, ZoneID: gs.ZoneID}})
			if gs.Name != "" && d.NPCs[gs.NPCID] == "" {
				d.NPCs[gs.NPCID] = gs.Name
			}
		case "vendor":
			it.Sources = append(it.Sources, Source{SoldBy: &SoldBySource{NPCID: gs.NPCID, NPCName: gs.Name, ZoneID: gs.ZoneID}})
		case "object":
			it.Sources = append(it.Sources, Source{Drop: &DropSource{ZoneID: gs.ZoneID, OtherName: gs.Name}})
		case "quest":
			it.Sources = append(it.Sources, Source{Quest: &QuestSource{ID: gs.NPCID, Name: gs.Name}})
		case "crafted":
			// NPCID carries the profession enum, ZoneID the craft spell
			it.Sources = append(it.Sources, Source{Crafted: &CraftedSource{Profession: gs.NPCID, SpellID: gs.ZoneID}})
		case "world":
			it.Sources = append(it.Sources, Source{Drop: &DropSource{OtherName: WorldDrop}})
		}
	}
}
